INSERT INTO public.feed_capacity_fixture VALUES(true,'synthetic-capacity-v1',now());
INSERT INTO feed.users(github_id,login,taxonomy_version,profile_version)
INSERT INTO public.feed_capacity_receipts SELECT 'synthetic-capacity-receipt-'||i, 'capacity-owner-'||lpad((i%10000)::text,5,'0')||'/synthetic-project-'||lpad(i::text,5,'0'),900000001+i/10,'app_submission',now()-interval '20 days' FROM generate_series(0,49999) i;
INSERT INTO public.feed_capacity_assessments SELECT 'synthetic-capacity-analysis-'||i,receipt_id,repo_key,true,jsonb_build_object('fixture','synthetic-capacity-v1','completed',true,'productScore',60+i%41,'confidence',80+i%21) FROM public.feed_capacity_receipts r JOIN generate_series(0,49999) i ON r.receipt_id='synthetic-capacity-receipt-'||i;
INSERT INTO feed.projects(repo_key,item_id,owner_login,name,canonical_url,summary,project_type,lifecycle,product_score,confidence,verification_level,exposure_band,treasure_eligible,analysis_id,resolved_commit_sha,analyzed_at,descriptor,descriptor_hash,source_hash,publishable)
INSERT INTO feed.project_submission_evidence(repo_key,source_kind,source_id,submitted_at,analysis_id)
INSERT INTO feed.project_tags(repo_key,tag_id,source,weight,confidence,evidence_ids,analysis_id,taxonomy_version)
INSERT INTO feed.user_tag_preferences(github_id,tag_id,value,source,strength,taxonomy_version) SELECT u.github_id,t.id,1,'explicit',1,1 FROM feed.users u CROSS JOIN feed.tag_definitions t WHERE t.id IN('artifact:micro-tool','stage:active-evolution');
INSERT INTO feed.requests(id,github_id,algorithm_version,taxonomy_version,profile_version,seed,candidate_counts,created_at) SELECT 'synthetic-capacity-request-'||i,900000001+i,'baseline-v2-portable',1,1,'synthetic-capacity-fixture','{"fixture":10}',now()-interval '15 days' FROM generate_series(0,4999) i;
INSERT INTO feed.served_items(request_id,repo_key,rank,candidate_sources,reason_codes,feature_snapshot,score,exploration,propensity,served_at)
INSERT INTO feed.events(id,github_id,repo_key,request_id,event_type,occurred_at,metadata)
