CREATE TABLE public.feed_capacity_fixture(id boolean PRIMARY KEY CHECK(id), fixture_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
 SELECT 900000001+i,'capacity-user-'||i,1,1 FROM generate_series(0,4999) i;
CREATE TABLE public.feed_capacity_receipts(receipt_id text PRIMARY KEY,repo_key text UNIQUE NOT NULL,github_id bigint REFERENCES feed.users(github_id) ON DELETE SET NULL,source_kind text NOT NULL CHECK(source_kind='app_submission'),submitted_at timestamptz NOT NULL);
CREATE TABLE public.feed_capacity_assessments(analysis_id text PRIMARY KEY,receipt_id text NOT NULL REFERENCES public.feed_capacity_receipts(receipt_id),repo_key text UNIQUE NOT NULL,completed boolean NOT NULL CHECK(completed),analysis_json jsonb NOT NULL);
 SELECT a.repo_key,replace(a.repo_key,'/',':'),split_part(a.repo_key,'/',1),split_part(a.repo_key,'/',2),'https://github.com/'||a.repo_key,'Synthetic capacity fixture only','cli','usable',(a.analysis_json->>'productScore')::float,(a.analysis_json->>'confidence')::float,'verified','low',true,a.analysis_id,repeat('a',40),now()-make_interval(secs=>i),'synthetic capacity fixture',repeat(md5(a.repo_key),2),repeat(md5(a.analysis_json::text),2),a.completed FROM public.feed_capacity_assessments a JOIN generate_series(0,49999) i ON a.analysis_id='synthetic-capacity-analysis-'||i;
 SELECT a.repo_key,r.source_kind,r.receipt_id,r.submitted_at,a.analysis_id FROM public.feed_capacity_assessments a JOIN public.feed_capacity_receipts r USING(receipt_id);
 SELECT p.repo_key,t.id,'system',0.8,0.9,jsonb_build_array(e.source_id),p.analysis_id,1 FROM feed.projects p JOIN feed.project_submission_evidence e USING(repo_key) CROSS JOIN feed.tag_definitions t WHERE t.id IN('artifact:micro-tool','stage:active-evolution');
 SELECT 'synthetic-capacity-request-'||(i/10),repo_key,i%10,'["quality"]','[]','{}',0.8,false,1,now()-interval '15 days' FROM public.feed_capacity_receipts r JOIN generate_series(0,49999) i ON r.receipt_id='synthetic-capacity-receipt-'||i;
 WITH samples AS (SELECT i,CASE WHEN i<=250000 THEN 0 ELSE 1+((i-250001)%4999) END actor,(i-1)%10 rank FROM generate_series(1,1000000) i)
 SELECT substring(md5('synthetic-capacity-event-'||i),1,8)||'-'||substring(md5('synthetic-capacity-event-'||i),9,4)||'-4'||substring(md5('synthetic-capacity-event-'||i),14,3)||'-8'||substring(md5('synthetic-capacity-event-'||i),18,3)||'-'||substring(md5('synthetic-capacity-event-'||i),21,12),900000001+actor,r.repo_key,'synthetic-capacity-request-'||actor,CASE WHEN i%2=0 THEN 'impression' ELSE 'detail_open' END,now()-interval '15 days'+make_interval(secs=>i%86400),jsonb_build_object('rank',rank,'algorithmVersion','baseline-v2-portable') FROM samples s JOIN public.feed_capacity_receipts r ON r.receipt_id='synthetic-capacity-receipt-'||(actor*10+rank);
